```javascript
import { moveItem, moveToFront, moveToBack } from '@semantic-ui/utils';

const items = ['a', 'b', 'c', 'd'];

moveItem(items, 1, 3);           // ['a', 'c', 'd', 'b'] - move 'b' to position 3
moveToFront(items, 'c');         // ['c', 'a', 'b', 'd'] - move 'c' to front
moveToBack(items, 'a');          // ['c', 'b', 'd', 'a'] - move 'a' to back
